function supervisor_column(int $n):string {$out='';while($n>0){$n--;$out=chr(65+$n%26).$out;$n=intdiv($n,26);}return $out;}
function supervisor_column_number(string $column):int {$n=0;foreach(str_split($column)as$c)$n=$n*26+ord($c)-64;return $n;}
function supervisor_sheets(PharData $zip):array {
 if(!isset($zip['xl/workbook.xml'],$zip['xl/_rels/workbook.xml.rels']))throw new CatalogException('El Excel no tiene hojas disponibles.',422);
 $rels=supervisor_xml($zip['xl/_rels/workbook.xml.rels']->getContent());$paths=[];
 foreach($rels->getElementsByTagName('Relationship')as$rel){if($rel->getAttribute('TargetMode')==='External')continue;$target=$rel->getAttribute('Target');$path=str_starts_with($target,'/')?ltrim($target,'/'):'xl/'.$target;if(preg_match('~^xl/worksheets/[A-Za-z0-9_-]+\.xml$~D',$path)&&isset($zip[$path]))$paths[$rel->getAttribute('Id')]=$path;}
 $out=[];$doc=supervisor_xml($zip['xl/workbook.xml']->getContent());foreach($doc->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'sheet')as$sheet){$id=$sheet->getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');if(isset($paths[$id]))$out[]=['value'=>$paths[$id],'label'=>$sheet->getAttribute('name')];if(count($out)>30)throw new CatalogException('El Excel admite hasta 30 hojas.',422);}
 if(!$out)throw new CatalogException('El Excel no tiene hojas compatibles.',422);return $out;
}
function supervisor_sheet(PharData $zip):string {return supervisor_sheets($zip)[0]['value'];}
function supervisor_ean(string $value):string {
 $value=trim($value);$numeric=str_replace(',','.',$value);
 if(preg_match('/^[0-9]+(?:\.[0-9]+)?(?:[Ee]\+?[0-9]+)?$/D',$numeric)&&preg_match('/[Ee.]/',$numeric)&&is_finite((float)$numeric)&&(float)$numeric<=9999999999999&&(float)$numeric===floor((float)$numeric)){ $expanded=sprintf('%.0f',(float)$numeric);$mantissa=preg_split('/[Ee]/',$numeric)[0];if(preg_match('/[Ee]/',$numeric)&&strlen(ltrim(str_replace('.','',$mantissa),'0'))<strlen($expanded))return $value;return $expanded;}
 return $value;
}
function supervisor_ean_heading(string $value):bool {return (bool)preg_match('/^(?:ean(?:[ -]?(?:8|13))?|gtin(?:[ -]?(?:8|13))?|barcode|c[oó]digo(?: de)?(?: barras| de barras)?)$/iu',trim($value));}
function supervisor_detect(array $rows):array {
 $counts=[];$heading=null;foreach($rows as$r=>$cells){foreach($cells as$c=>$cell){if(!$cell['formula']&&valid_product_ean(supervisor_ean($cell['value'])))$counts[$c]=($counts[$c]??0)+1;if($r<=100&&supervisor_ean_heading($cell['value'])&&$heading===null)$heading=[$r,$c];}}
