}
function supervisor_cells(PharData $zip,string $path):array {
 $shared=[];if(isset($zip['xl/sharedStrings.xml']))foreach(supervisor_xml($zip['xl/sharedStrings.xml']->getContent())->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'si')as$si){$text='';foreach($si->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'t')as$t)$text.=$t->textContent;$shared[]=$text;if(count($shared)>50000)throw new CatalogException('El Excel tiene demasiadas celdas.',422);}
 $sheet=supervisor_xml($zip[$path]->getContent());$rows=[];$max=0;$count=0;foreach($sheet->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'row')as$row){$r=(int)$row->getAttribute('r');if($r<1||$r>10001)throw new CatalogException('La lista admite hasta 10.000 filas de productos.',422);foreach($row->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'c')as$cell){if(++$count>100000)throw new CatalogException('El Excel tiene demasiadas celdas.',422);if(!preg_match('/^([A-Z]{1,3})[0-9]+$/D',$cell->getAttribute('r'),$m))throw new CatalogException('El Excel tiene referencias de celda no válidas.',422);$col=$m[1];$number=supervisor_column_number($col);if($number>200)throw new CatalogException('La lista admite hasta 200 columnas.',422);$max=max($max,$number);$value=$cell->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'v')->item(0)?->textContent??'';if($cell->getAttribute('t')==='s')$value=$shared[(int)$value]??'';elseif($cell->getAttribute('t')==='inlineStr'){$value='';foreach($cell->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'t')as$t)$value.=$t->textContent;}$rows[$r][$col]=['value'=>$value,'formula'=>$cell->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'f')->length>0];}}
 return [$sheet,$rows,$max];
}
function supervisor_parse_xlsx(string $bytes,string $column='',array $options=[]):array {
 return supervisor_archive($bytes,function($zip)use($column,$options){$sheets=supervisor_sheets($zip);$path=$options['sheet']??'';
 if($path!==''&&!in_array($path,array_column($sheets,'value'),true))throw new CatalogException('Elegí una hoja del Excel.',422);
 $best=-1;$selected=null;foreach($sheets as$sheet){if($path!==''&&$sheet['value']!==$path)continue;[, $candidate,$max]=supervisor_cells($zip,$sheet['value']);$detected=supervisor_detect($candidate);$score=$detected['count']+($detected['header']?10000:0);if($score>$best){$best=$score;$selected=[$sheet['value'],$candidate,$max,$detected];}}
 [$path,$rows,$max,$detected]=$selected;$header=$options['header']??'';if($header==='')$header=$detected['header'];elseif(!preg_match('/^[0-9]{1,5}$/D',(string)$header)||(int)$header>10000)throw new CatalogException('Revisá la fila de títulos.',422);$header=(int)$header;if($header&&!isset($rows[$header]))throw new CatalogException('Esa fila no existe en la hoja.',422);
 $columns=[];for($i=1;$i<=$max;$i++){$c=supervisor_column($i);$label=$header?trim($rows[$header][$c]['value']??''):'';$columns[]=['value'=>$c,'label'=>$c.' · '.($label?:'Sin título')];}
 $chosen=$column?:$detected['column'];if(!preg_match('/^[A-Z]{1,2}$/D',$chosen)||supervisor_column_number($chosen)>$max)throw new CatalogException('Elegí la columna de EAN.',422);
 $fixes=json_decode($options['corrections']??'{}',true);if(!is_array($fixes)||count($fixes)>100)throw new CatalogException('Revisá las correcciones de EAN.',422);foreach($fixes as$r=>$v)if(!ctype_digit((string)$r)||!is_string($v)||strlen($v)>60)throw new CatalogException('Revisá las correcciones de EAN.',422);
 $eanRows=[];$issues=[];$samples=[];foreach($rows as$r=>$cells){if($r<=$header)continue;$cell=$cells[$chosen]??['value'=>'','formula'=>false];$raw=trim($cell['value']);if($raw==='')continue;if(supervisor_ean_heading($raw))continue;
 $ean=supervisor_ean($fixes[$r]??$raw);$reason=$cell['formula']?'El código contiene una fórmula.':(!preg_match('/^[0-9]{8}$|^[0-9]{13}$/D',$ean)?'Código incompleto o con caracteres extraños.':(!valid_product_ean($ean)?'El dígito de control no coincide.':''));
