function supervisor_export_layout(DOMDocument $doc,int $start,array $columns):array {
 $cols=$doc->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'cols')->item(0);if(!$cols){$cols=$doc->createElementNS(SUPERVISOR_XLSX_NS,'cols');$doc->documentElement->insertBefore($cols,$doc->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'sheetData')->item(0));}$widths=[];$i=$start;foreach($columns as$key=>$label){$width=match($key){'stock'=>19,'ean'=>19,'uxb'=>29,'name'=>38,'expires'=>40,'pallets'=>57,default=>36};$col=$doc->createElementNS(SUPERVISOR_XLSX_NS,'col');$col->setAttribute('min',(string)$i);$col->setAttribute('max',(string)$i++);$col->setAttribute('width',(string)$width);$col->setAttribute('customWidth','1');$cols->appendChild($col);$widths[$key]=$width;}return $widths;
