function supervisor_row_height(DOMElement $row,array $values,array $widths):void {$lines=1;foreach($values as$key=>$value){$needed=0;foreach(explode("\n",(string)$value)as$line)$needed+=max(1,(int)ceil(mb_strlen($line)/max(1,($widths[$key]??36)*.85)));$lines=max($lines,$needed);}if($lines>1){$row->setAttribute('ht',(string)max((float)$row->getAttribute('ht'),min(409,15*$lines+4)));$row->setAttribute('customHeight','1');}}
