 $columns??=['stock'=>'Stock (unidades)'];return supervisor_archive($bytes,function($zip)use($path,$eanRows,$totals,$header,$columns,$details){if(!preg_match('~^xl/worksheets/[A-Za-z0-9_-]+\.xml$~D',$path)||!isset($zip[$path]))throw new CatalogException('La hoja ya no está disponible.',422);[$doc,$originalRows,$max]=supervisor_cells($zip,$path);$header??=1;$format=array_keys($columns)!==['stock'];$style=$format?supervisor_wrap_style($zip):null;$widths=$format?supervisor_export_layout($doc,$max+1,$columns):[];$written=0;
